create or replace function public.provision_verified_member() returns trigger language plpgsql security definer set search_path=public as $$ begin if new.email_confirmed_at is null or new.email is null then return new; end if; insert into public.members(id) values(new.id) on conflict(id) do nothing; insert into public.member_private(id,email) values(new.id,new.email) on conflict(id) do update set email=excluded.email,updated_at=now(); return new; end; $$;
create trigger on_verified_auth_user after insert or update of email_confirmed_at,email on auth.users for each row execute function public.provision_verified_member();
create or replace function public.ensure_my_onboarding_profile() returns public.members language plpgsql security definer set search_path=public,auth as $$ declare account auth.users%rowtype; profile public.members%rowtype; begin select * into account from auth.users where id=auth.uid(); if account.id is null or account.email_confirmed_at is null or account.email is null then raise exception 'Verify your email before starting onboarding'; end if; insert into public.members(id) values(account.id) on conflict(id) do nothing; insert into public.member_private(id,email) values(account.id,account.email) on conflict(id) do update set email=excluded.email,updated_at=now(); select * into profile from public.members where id=account.id; return profile; end; $$;
create or replace function public.save_my_onboarding_progress(p_updates jsonb) returns public.members language plpgsql security definer set search_path=public as $$ declare profile public.members%rowtype; supplied_dob date; begin if auth.uid() is null then raise exception 'Sign in required'; end if; perform public.ensure_my_onboarding_profile(); if p_updates?'date_of_birth' then supplied_dob:=(p_updates->>'date_of_birth')::date; update public.member_private set date_of_birth=supplied_dob,updated_at=now() where id=auth.uid() and date_of_birth is null; if not found then raise exception 'Date of birth is already stored and cannot be changed here'; end if; end if; update public.members set display_name=case when p_updates?'display_name' then left(trim(p_updates->>'display_name'),80) else display_name end,photo_url=case when p_updates?'photo_url' then nullif(left(trim(p_updates->>'photo_url'),2048),'') else photo_url end,bio=case when p_updates?'bio' then left(trim(p_updates->>'bio'),1000) else bio end,city=case when p_updates?'city' then left(trim(p_updates->>'city'),120) else city end,country=case when p_updates?'country' then left(trim(p_updates->>'country'),120) else country end,onboarding_updated_at=now(),updated_at=now() where id=auth.uid() returning * into profile; return profile; end; $$;
create or replace function public.complete_my_onboarding() returns public.members language plpgsql security definer set search_path=public as $$ declare profile public.members%rowtype; has_dob boolean; begin perform public.ensure_my_onboarding_profile(); select * into profile from public.members where id=auth.uid(); select date_of_birth is not null into has_dob from public.member_private where id=auth.uid(); if coalesce(trim(profile.display_name),'')='' then raise exception 'Display name is required'; end if; if profile.photo_url is null then raise exception 'Profile photo is required'; end if; if not coalesce(has_dob,false) then raise exception 'Date of birth is required'; end if; update public.members set onboarding_completed=true,onboarding_updated_at=now(),updated_at=now() where id=auth.uid() returning * into profile; return profile; end; $$;
revoke all on function public.provision_verified_member() from public; grant execute on function public.ensure_my_onboarding_profile() to authenticated; grant execute on function public.save_my_onboarding_progress(jsonb) to authenticated; grant execute on function public.complete_my_onboarding() to authenticated;
